{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://github.com/vunm-io/passdown/schemas/protocol/result.v1.schema.json",
  "title": "passdown.result/v1",
  "description": "The final payload a delegated worker returns for one attempt. The host validates it; it is evidence, never completion. Design: docs/design/PDN-0004-v05-acceptance-recovery.md section 7. Two rules need context this schema does not have and are enforced by the helper only: `attempt` must equal the receipt ID (diagnostic attempt-mismatch), and the payload must be one JSON object of at most 256 KiB (diagnostic parse).",
  "type": "object",
  "required": ["schema", "attempt", "disposition", "summary", "changed_paths", "evidence"],
  "properties": {
    "schema": { "const": "passdown.result/v1" },
    "attempt": { "$ref": "#/$defs/attemptId" },
    "disposition": { "enum": ["submitted", "needs_input", "blocked", "failed"] },
    "summary": { "type": "string", "minLength": 1, "maxLength": 2000 },
    "changed_paths": {
      "type": "array",
      "maxItems": 2000,
      "items": {
        "type": "object",
        "required": ["path", "change"],
        "properties": {
          "path": { "$ref": "#/$defs/relativePath" },
          "change": { "enum": ["added", "modified", "deleted", "renamed"] }
        },
        "patternProperties": { "^x_": true },
        "additionalProperties": false
      }
    },
    "evidence": {
      "type": "array",
      "maxItems": 200,
      "items": {
        "type": "object",
        "required": ["kind"],
        "properties": {
          "kind": { "enum": ["command", "observation"] },
          "command": { "type": "string", "minLength": 1, "maxLength": 2000 },
          "exit_code": { "type": "integer" },
          "observed": { "type": "string", "maxLength": 4000 }
        },
        "patternProperties": { "^x_": true },
        "additionalProperties": false,
        "allOf": [
          {
            "if": { "properties": { "kind": { "const": "command" } } },
            "then": { "required": ["command", "exit_code"] },
            "else": { "required": ["observed"], "not": { "anyOf": [ { "required": ["command"] }, { "required": ["exit_code"] } ] } }
          }
        ]
      }
    },
    "assumptions": { "$ref": "#/$defs/notes" },
    "caveats": { "$ref": "#/$defs/notes" },
    "question": {
      "oneOf": [
        { "type": "null" },
        {
          "type": "object",
          "required": ["text"],
          "properties": {
            "text": { "type": "string", "minLength": 1, "maxLength": 2000 },
            "options": {
              "type": "array",
              "maxItems": 20,
              "items": { "type": "string", "minLength": 1, "maxLength": 500 }
            },
            "context_paths": {
              "type": "array",
              "maxItems": 50,
              "items": { "$ref": "#/$defs/relativePath" }
            }
          },
          "patternProperties": { "^x_": true },
          "additionalProperties": false
        }
      ]
    },
    "blocker": {
      "oneOf": [
        { "type": "null" },
        {
          "type": "object",
          "required": ["kind", "message"],
          "properties": {
            "kind": { "enum": ["permission", "sandbox", "network", "tool-missing", "other"] },
            "message": { "type": "string", "minLength": 1, "maxLength": 8000 }
          },
          "patternProperties": { "^x_": true },
          "additionalProperties": false
        }
      ]
    }
  },
  "patternProperties": { "^x_": true },
  "additionalProperties": false,
  "allOf": [
    {
      "$comment": "question: present and non-empty iff needs_input",
      "if": { "properties": { "disposition": { "const": "needs_input" } } },
      "then": { "required": ["question"], "properties": { "question": { "type": "object" } } },
      "else": { "properties": { "question": { "type": "null" } } }
    },
    {
      "$comment": "blocker: present iff blocked",
      "if": { "properties": { "disposition": { "const": "blocked" } } },
      "then": { "required": ["blocker"], "properties": { "blocker": { "type": "object" } } },
      "else": { "properties": { "blocker": { "type": "null" } } }
    }
  ],
  "$defs": {
    "attemptId": {
      "type": "string",
      "pattern": "^pd-[0-9]{8}T[0-9]{6}Z-[0-9a-f]{8}$"
    },
    "relativePath": {
      "$comment": "Relative and normalized: non-empty segments separated by single slashes, no Windows drive prefix, no leading slash, no trailing slash, no backslash or NUL, no '.' or '..' segment.",
      "type": "string",
      "minLength": 1,
      "maxLength": 1024,
      "pattern": "^[^/\\\\\\x00]+(/[^/\\\\\\x00]+)*$",
      "not": { "pattern": "(^|/)\\.{1,2}(/|$)|^[A-Za-z]:" }
    },
    "notes": {
      "type": "array",
      "maxItems": 50,
      "items": { "type": "string", "minLength": 1, "maxLength": 1000 }
    }
  }
}

